<script setup lang="ts">
import { computed } from 'vue'
import { app, gs, open, selectToken, aimToken } from '../session'
import { CONDITIONS, EFFECTS } from '../rules/base'
import { levelReady, sheet } from '../rules/hero'
import Portrait from './Portrait.vue'
const list = computed(() => Object.entries(gs.value?.chars ?? {}).map(([id, h]) => ({ id, h, S: sheet(h), on: id === app.seat || (app.players.find(p => p.token === id)?.online ?? !app.hosting) })).sort((a, b) => +(b.id === app.seat) - +(a.id === app.seat))); const fx = (h: any) => h.conds.filter((c: any) => c.id !== 'unconscious').slice(0, 6).map((c: any) => ({ k: c.id, d: c.kind === 'fx' ? EFFECTS[c.id] : CONDITIONS[c.id] })).filter((x: any) => x.d)
const click = (id: string) => { if (app.aim) aimToken(id); else if (id === app.seat) open('sheet'); else if (app.role === 'dm') open('sheet', id); else selectToken(id) }
</script>
<template><div class="py"><button v-for="p in list" :key="p.id" :class="{ me: p.id === app.seat, dead: p.h.dead, away: !p.on, turn: gs?.combat && gs.combat.order[gs.combat.i]?.id === p.id }" :aria-label="p.h.name" @click="click(p.id)"><Portrait :hero="p.h" :size="p.id === app.seat ? 64 : 48" /><span class="t"><b class="cut">{{ p.h.name }}</b><span class="hp hero" :class="{ low: p.h.hp < p.S.max * .3 }"><i :style="{ width: Math.max(0, p.h.hp / p.S.max) * 100 + '%' }" /><u v-if="p.h.temp" :style="{ width: Math.min(100, p.h.temp / p.S.max * 100) + '%' }" /></span><em class="cut">{{ p.h.dead ? 'dead' : p.h.hp <= 0 ? (p.h.stable ? 'stable' : `dying, ${p.h.death.s} held, ${p.h.death.f} lost`) : p.h.shape ? `as ${p.h.shape.id.replace(/_/g, ' ')}` : !p.on ? 'away' : fx(p.h).map((f: any) => f.d.name.toLowerCase()).join(', ') || `level ${p.h.level}` }}<template v-if="p.h.insp">, inspired</template></em></span><strong v-if="!p.h.dead">{{ p.h.shape ? p.h.shape.hp : p.h.hp }}</strong><i v-if="levelReady(p.h) && p.id === app.seat" class="up" @click.stop="open('level')">Level up</i></button></div></template>
<style scoped>.py{display:grid;width:210px;pointer-events:auto}.py button{display:flex;align-items:center;background:var(--navy);border-bottom:1px solid var(--line2);flex-wrap:wrap;position:relative}.py button:hover{background:var(--navy2)}.py .turn::before{content:'';position:absolute;left:0;top:0;bottom:0;width:6px;background:var(--spot);z-index:1}.t{flex:1;min-width:0;display:grid;gap:3px;padding:0 4px 0 10px}.py b{font:700 18px/1 var(--serif)}.py em{font-style:normal;font-size:14px;line-height:1.05;color:var(--tx2)}.hp{height:7px}strong{font:800 27px/1 var(--serif);padding:0 11px 2px 4px}.dead{opacity:.55}.away{opacity:.7}.up{display:block;width:100%;background:var(--spot);color:var(--on-spot);padding:4px 10px;font-weight:600;font-style:normal}
@media(max-width:899px){.py{display:flex;width:100%;overflow-x:auto;scrollbar-width:none;background:var(--navy)}.py button{flex:none;width:152px;border-bottom:0;border-right:1px solid var(--line2);flex-wrap:nowrap}.py :deep(.pt){width:46px!important;height:52px!important}.py :deep(.pt img){object-fit:cover}.py em{font-size:13px}.py b{font-size:16.5px}strong{font-size:23px;padding-right:8px}.up{position:absolute;left:0;right:0;bottom:0;padding:2px 8px;font-size:14px}}</style>
